<?php
if (!defined('ROUTER_LOADED')) { http_response_code(403); exit('Accès direct interdit.'); }
if (!userCan($user, 'flux.sorties')) { http_response_code(403); echo '<div class="rounded-md border border-red-200 bg-red-50 p-4 text-red-700">Accès refusé.</div>'; return; }
require_once __DIR__ . '/../../api/database.php';
require_once __DIR__ . '/_inventory.php';
$db=Database::getInstance();
$products=$db->fetchAll('SELECT id, medicine_name, actual_quantity, sell_type FROM stock WHERE is_archived = 0 AND actual_quantity > 0 ORDER BY medicine_name');
$productId=(int)($_GET['product_id'] ?? $_POST['product_id'] ?? 0);
$productIds=array_values((array)($_POST['product_id']??[$productId ?: ''])); $quantities=array_values((array)($_POST['quantity']??['1'])); $workshop=''; $beneficiary=''; $workReference=''; $reason=''; $errors=[]; inventoryEnsureCsrf();
if (empty($_SESSION['internal_issue_token'])) $_SESSION['internal_issue_token']=bin2hex(random_bytes(32));
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
    $productIds=array_values((array)($_POST['product_id']??[])); $quantities=array_values((array)($_POST['quantity']??[])); $workshop=trim((string)($_POST['workshop']??'')); $beneficiary=trim((string)($_POST['beneficiary']??'')); $workReference=trim((string)($_POST['work_reference']??'')); $reason=trim((string)($_POST['reason']??''));
    if (!hash_equals($_SESSION['csrf_token'],(string)($_POST['csrf_token']??''))) $errors[]='Le formulaire a expiré. Rechargez puis réessayez.';
    if (!hash_equals($_SESSION['internal_issue_token'],(string)($_POST['issue_token']??''))) $errors[]='Cette sortie a déjà été traitée ou le formulaire a expiré. Rechargez la page avant de réessayer.';
    if ($workshop===''||mb_strlen($workshop)>60) $errors[]='Indiquez un atelier destinataire (60 caractères maximum).';
    if (mb_strlen($beneficiary)>60||mb_strlen($workReference)>60||$reason===''||mb_strlen($reason)>200) $errors[]='Vérifiez le bénéficiaire, la référence de travail et le motif (200 caractères maximum).';
    $lineInputs=[]; $seen=[]; $rowCount=max(count($productIds),count($quantities));
    if ($rowCount>50) $errors[]='Une sortie ne peut pas contenir plus de 50 articles.';
    for($index=0;$index<min($rowCount,50);$index++){
        $lineProductId=(int)($productIds[$index]??0); $quantityText=str_replace(',', '.', trim((string)($quantities[$index]??'')));
        if($lineProductId<=0&&$quantityText==='')continue;
        if($lineProductId<=0||!is_numeric($quantityText)||!is_finite((float)$quantityText)||(float)$quantityText<=0){$errors[]='Chaque ligne doit contenir un article et une quantité supérieure à zéro.';continue;}
        if(isset($seen[$lineProductId])){$errors[]='Un article ne peut apparaître qu’une fois; regroupez sa quantité sur la même ligne.';continue;}
        $seen[$lineProductId]=true; $lineInputs[]=['id'=>$lineProductId,'quantity'=>round((float)$quantityText,2)];
    }
    if(!$lineInputs)$errors[]='Ajoutez au moins un article à la sortie.';
    if (!$errors) {
        $pdo=$db->getPdo();
        try {
            $pdo->beginTransaction();
            $idsToLock=array_column($lineInputs,'id'); sort($idsToLock,SORT_NUMERIC); $productsById=[];
            foreach($idsToLock as $idToLock){$product=$db->query('SELECT * FROM stock WHERE id = ? FOR UPDATE',[$idToLock])->fetch();if(!$product||(int)$product['is_archived']===1)throw new RuntimeException('Un des articles est introuvable ou archiv?.');$productsById[(int)$idToLock]=$product;}
            foreach($lineInputs as $line){$product=$productsById[$line['id']];if($line['quantity']>(float)$product['actual_quantity'])throw new RuntimeException('Stock insuffisant pour « '.$product['medicine_name'].' » : disponible '.number_format((float)$product['actual_quantity'],2,',',' ').' '.$product['sell_type'].'.');}
            $issueNumber='INT-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(4)));
            $movementReason='Sortie interne vers atelier: '.$workshop.'; Bénéficiaire: '.($beneficiary ?: 'Non précisé').'; Motif: '.$reason.'; Réf. travail: '.($workReference ?: '—');
            foreach($lineInputs as $line){$product=$productsById[$line['id']];$quantity=$line['quantity'];$before=(float)$product['actual_quantity'];$after=round($before-$quantity,2);$status=$after<=0?'Rupture':'Disponible';$db->execute('UPDATE stock SET actual_quantity = ?, used_quantity = used_quantity + ?, status = ? WHERE id = ?',[$after,$quantity,$status,$line['id']]);inventoryLogMovement($db,$product,'sortie',$quantity,$before,$after,(float)$product['actual_price'],$issueNumber,$movementReason,$user['nom_complet']);}
            $pdo->commit();
            $_SESSION['internal_issue_token']=bin2hex(random_bytes(32));
            $_SESSION['flash_message']=['type'=>'success','text'=>'Sortie interne '.$issueNumber.' enregistrée pour '.count($lineInputs).' article(s) vers '.$workshop.'.'];
            header('Location: '.app_route_url('stock/mouvements')); exit;
        } catch (Throwable $error) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            error_log('Stock exit failed: '.$error->getMessage());
            $errors[]=$error instanceof RuntimeException?$error->getMessage():'La sortie n’a pas pu être enregistrée.';
        }
    }
}
?>
<section class="mx-auto max-w-3xl space-y-5"><header><a href="<?= inventoryEscape(app_route_url('stock')) ?>" class="inline-flex items-center gap-2 text-sm font-medium text-green-800"><i data-feather="arrow-left" class="h-4 w-4"></i> État du stock</a><div class="mt-3"><p class="text-sm font-semibold text-rose-700">Mouvement interne</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Sortie vers un atelier</h1><p class="mt-1 text-sm text-slate-600">Cette opération décrémente le stock et n’émet aucune facture ni écriture de caisse.</p></div></header>
<?php if ($errors): ?><div role="alert" class="rounded-md border border-red-200 bg-red-50 p-4 text-sm text-red-800"><ul class="list-disc pl-5"><?php foreach(array_unique($errors) as $error): ?><li><?= inventoryEscape($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if (!$products): ?><div class="rounded-md border border-amber-200 bg-amber-50 p-4 text-amber-900">Aucun produit n’a de quantité disponible à sortir.</div><?php endif; ?>
<form method="post" class="space-y-5 rounded-md border border-slate-200 bg-white p-5"><input type="hidden" name="csrf_token" value="<?= inventoryEscape($_SESSION['csrf_token']) ?>"><input type="hidden" name="issue_token" value="<?= inventoryEscape($_SESSION['internal_issue_token']) ?>">
<fieldset class="space-y-3"><div class="flex items-center justify-between gap-3"><legend class="text-sm font-semibold">Articles remis</legend><button type="button" id="addInternalLine" class="inline-flex items-center gap-2 rounded-md border border-green-200 bg-green-50 px-3 py-2 text-sm font-semibold text-green-800 hover:bg-green-100" <?= !$products?'disabled':'' ?>><?= inventoryLineActionIcon('add') ?> Ajouter un article</button></div><div id="internalLines" class="space-y-3">
<?php foreach($productIds as $lineIndex=>$selectedId): ?><div class="internal-line grid gap-3 rounded-md border border-slate-200 p-3 sm:grid-cols-[minmax(0,1fr)_9rem_auto] sm:items-end"><label class="space-y-1 text-sm font-medium">Article<select name="product_id[]" required class="internal-product w-full rounded-md border border-slate-300 bg-white px-3 py-2.5 font-normal"><option value="">Choisir un article</option><?php foreach($products as $product): ?><option value="<?= (int)$product['id'] ?>" <?= (string)$selectedId===(string)$product['id']?'selected':'' ?>><?= inventoryEscape($product['medicine_name']) ?> · disponible <?= number_format((float)$product['actual_quantity'],2,',',' ') ?> <?= inventoryEscape($product['sell_type']) ?></option><?php endforeach; ?></select></label><label class="space-y-1 text-sm font-medium">Quantité remise<input name="quantity[]" type="number" min="0.01" step="0.01" required value="<?= inventoryEscape($quantities[$lineIndex]??'1') ?>" class="w-full rounded-md border border-slate-300 px-3 py-2.5 font-normal"></label><button type="button" class="remove-internal-line inline-flex items-center justify-center rounded-md border border-rose-200 bg-rose-50 p-2.5 text-rose-700 hover:bg-rose-100" aria-label="Retirer l’article" title="Retirer l’article"><?= inventoryLineActionIcon('remove') ?></button></div><?php endforeach; ?>
</div></fieldset>
<div class="grid gap-4 border-t border-slate-100 pt-4 sm:grid-cols-2"><label class="space-y-1 text-sm font-medium">Atelier destinataire <span class="text-red-600">*</span><input name="workshop" maxlength="60" required value="<?= inventoryEscape($workshop) ?>" class="w-full rounded-md border border-slate-300 px-3 py-2.5 font-normal"></label><label class="space-y-1 text-sm font-medium">Bénéficiaire<input name="beneficiary" maxlength="60" value="<?= inventoryEscape($beneficiary) ?>" class="w-full rounded-md border border-slate-300 px-3 py-2.5 font-normal"></label><label class="space-y-1 text-sm font-medium">Référence du travail<input name="work_reference" maxlength="60" value="<?= inventoryEscape($workReference) ?>" class="w-full rounded-md border border-slate-300 px-3 py-2.5 font-normal"></label><label class="space-y-1 text-sm font-medium sm:col-span-2">Motif <span class="text-red-600">*</span><textarea name="reason" maxlength="200" rows="3" required class="w-full rounded-md border border-slate-300 px-3 py-2.5 font-normal"><?= inventoryEscape($reason) ?></textarea></label></div>
<div class="flex justify-end border-t pt-4"><button class="rounded-md bg-rose-700 px-4 py-2.5 text-sm font-semibold text-white" <?= !$products?'disabled':'' ?>>Confirmer la sortie interne</button></div></form></section>
<template id="internalLineTemplate"><div class="internal-line grid gap-3 rounded-md border border-slate-200 p-3 sm:grid-cols-[minmax(0,1fr)_9rem_auto] sm:items-end"><label class="space-y-1 text-sm font-medium">Article<select name="product_id[]" required class="internal-product w-full rounded-md border border-slate-300 bg-white px-3 py-2.5 font-normal"><option value="">Choisir un article</option><?php foreach($products as $product): ?><option value="<?= (int)$product['id'] ?>"><?= inventoryEscape($product['medicine_name']) ?> · disponible <?= number_format((float)$product['actual_quantity'],2,',',' ') ?> <?= inventoryEscape($product['sell_type']) ?></option><?php endforeach; ?></select></label><label class="space-y-1 text-sm font-medium">Quantité remise<input name="quantity[]" type="number" min="0.01" step="0.01" required value="1" class="w-full rounded-md border border-slate-300 px-3 py-2.5 font-normal"></label><button type="button" class="remove-internal-line inline-flex items-center justify-center rounded-md border border-rose-200 bg-rose-50 p-2.5 text-rose-700 hover:bg-rose-100" aria-label="Retirer l’article" title="Retirer l’article"><?= inventoryLineActionIcon('remove') ?></button></div></template>
<script>(()=>{const lineContainer=document.getElementById('internalLines');const addButton=document.getElementById('addInternalLine');const template=document.getElementById('internalLineTemplate');if(!lineContainer||!addButton||!template)return;addButton.addEventListener('click',()=>{if(lineContainer.children.length>=50)return;lineContainer.append(template.content.cloneNode(true));if(window.feather)feather.replace();});lineContainer.addEventListener('click',event=>{const removeButton=event.target.closest('.remove-internal-line');if(!removeButton)return;const rows=lineContainer.querySelectorAll('.internal-line');if(rows.length>1)removeButton.closest('.internal-line').remove();else{rows[0].querySelector('.internal-product').value='';rows[0].querySelector('input[name="quantity[]"]').value='1';}});})();</script>
